fn rjust(orig: Vec<char>, width: u8, fillchar: char) -> Vec<char> {
    let orig_len = orig.len();
    let target_width = width as usize;

    if orig_len >= target_width {
        // Original is already at least target width, return unchanged.
        orig
    } else {
        // Need to pad on the left with fillchar
        let mut res = Vec::with_capacity(target_width);
        // Number of fill chars needed
        let pad_len = target_width - orig_len;
        res.extend(std::iter::repeat(fillchar).take(pad_len));
        res.extend(orig);
        res
    }
}